info.additionalInfo:
/* Baby Pastel Theme for Google Classroom */

@-moz-document url-prefix("https://classroom.google.com/") {
  /* Main background: soft baby blue */
  body, .material-design {
    background-color: #E0F7FA !important;
  }

  /* Sidebars and panels: gentle baby pink */
  .a-f-i, .Pc {
    background-color: #F8BBD0 !important;
  }

  /* Top bar / header: subtle baby purple */
  header, .aqa {
    background-color: #E1BEE7 !important;
  }

  /* Cards (classes, stream items): white with pastel borders */
  .J3vvPb, .kVDNFe {
    background-color: #FFFFFF !important;
    border: 2px solid #CE93D8 !important; /* baby purple border */
    border-radius: 8px !important;
  }

  /* Buttons and interactive elements: pastel blend on hover */
  .zgpbbe, .U26fgb {
    background-color: #F8BBD0 !important;
    color: #000 !important;
    border: none !important;
    border-radius: 6px !important;
  }
  .zgpbbe:hover, .U26fgb:hover {
    background-color: #E1BEE7 !important;
  }

  /* Text links: baby blue */
  a, .a-ud {
    color: #0288D1 !important;
  }

  /* Dialogs, overlays: soft pink background */
  .Yc, .oKrFZd {
    background-color: rgba(248, 187, 208, 0.9) !important;
  }

  /* Accent highlights (e.g., selected tabs): baby purple */
  .UxM5Ld, .Kj-JD-Jz {
    background-color: #CE93D8 !important;
  }

  /* Scrollbars: pastel track and thumb */
  ::-webkit-scrollbar {
    width: 10px;
  }
  ::-webkit-scrollbar-track {
    background: #E0F7FA;
  }
  ::-webkit-scrollbar-thumb {
    background: #F8BBD0;
    border-radius: 5px;
  }

  /* Optional: lighten form fields a bit */
  input, textarea {
    background-color: #FFFFFF !important;
    color: #333 !important;
    border: 1px solid #CE93D8 !important;
  }
}

